insert into core.geographies(id,country_code,geography_type,name,slug,metadata,status) values(md5('sg:city:singapore')::uuid,'SG','city','Singapore','singapore',jsonb_build_object('source_tier','official_institution','normalization_batch','sg_au_locations_v1'),'active') on conflict(id) do update set name=excluded.name,slug=excluded.slug,metadata=coalesce(core.geographies.metadata,'{}'::jsonb)||excluded.metadata,status=excluded.status,updated_at=now(); with location_rows(uen,location_name,address_line,postal_code,source_url) as (values ('200604346E','Kent Ridge / University Hall','21 Lower Kent Ridge Road','119077','https://www.nus.edu.sg/contact'),('200604393R','Main Campus','50 Nanyang Avenue','639798','https://www.ntu.edu.sg/ncpa/about-us/contact-us'),('200000267Z','Administration Building','81 Victoria Street','188065','https://www.smu.edu.sg/about/contact'),('200913519C','SUTD Campus','8 Somapah Road','487372','https://www.sutd.edu.sg/contact-us/contact-sutd/'),('200917667D','Punggol Campus','1 Punggol Coast Road','828608','https://www.singaporetech.edu.sg/campus-locations'),('200504979Z','Clementi Campus','463 Clementi Road','599494','https://www.suss.edu.sg/contact-us')), resolved as (select identity.institution_id,identity.uen,l.location_name,l.address_line,l.postal_code,l.source_url,g.id geography_id from location_rows l join public.institution_identity_sg_v1 identity on identity.uen=l.uen join core.geographies g on g.country_code='SG' and g.geography_type='city' and g.slug='singapore' and g.status='active') insert into catalog.campuses(id,institution_id,name,city,locality,country_code,geography_id,locality_geography_id,address_line,postal_code,official_url,source_url,source_checked_at,metadata,status) select md5('sg:au-location:'||uen)::uuid,institution_id,location_name,'Singapore','Singapore','SG',geography_id,geography_id,address_line,postal_code,source_url,source_url,now(),jsonb_build_object('record_scope','official_primary_location','location_quality','verified_official','display_policy','preferred','source_tier','official_institution','uen',uen,'location_key','official-primary-address','coordinate_precision','not_asserted','programme_assignment_verified',false,'normalization_batch','sg_au_locations_v1'),'active' from resolved on conflict(id) do update set name=excluded.name,city=excluded.city,locality=excluded.locality,geography_id=excluded.geography_id,locality_geography_id=excluded.locality_geography_id,address_line=excluded.address_line,postal_code=excluded.postal_code,official_url=excluded.official_url,source_url=excluded.source_url,source_checked_at=excluded.source_checked_at,metadata=excluded.metadata,status=excluded.status,updated_at=now(); create or replace view public.institution_location_sg_v1 with(security_invoker=true) as select c.institution_id,c.id campus_id,c.name,g.name city_name,g.slug city_slug,coalesce(nullif(c.city,''),nullif(c.locality,'')) reported_city,c.region,c.address_line,c.postal_code,c.official_url,c.source_url,c.source_checked_at,c.metadata->>'location_quality' location_quality,c.metadata->>'record_scope' record_scope,c.metadata->>'uen' uen from catalog.campuses c join catalog.institutions i on i.id=c.institution_id and i.country_code='SG' left join core.geographies g on g.id=coalesce(c.locality_geography_id,c.geography_id) and g.status='active' where c.status<>'inactive' and c.metadata->>'location_quality'='verified_official'; revoke all on public.institution_location_sg_v1 from public,anon,authenticated; grant select on public.institution_location_sg_v1 to service_role; do $$ declare c int; begin select count(*) into c from public.institution_location_sg_v1; if c<>6 then raise exception 'Expected 6 SG locations, found %',c; end if; select count(*) into c from public.institution_location_sg_v1 where address_line is null or postal_code !~ '^[0-9]{6}$'; if c>0 then raise exception 'Invalid SG location address rows %',c; end if; select count(*) into c from catalog.campuses cp join catalog.institutions i on i.id=cp.institution_id where i.country_code='SG' and cp.status<>'inactive' and cp.metadata->>'location_quality'='verified_official' and (cp.latitude is not null or cp.longitude is not null); if c>0 then raise exception 'SG official locations assert coordinates %',c; end if; end $$;;
